import { getNasaReferenceList } from '../data/nasaReferences';
import type {
  AiAssessment,
  AiCategoryKey,
  AiCategoryScores,
  AiDeductionItem,
  AiMissionEvaluationReport,
  MissionEvaluationRequestPayload,
} from '../types/aiEvaluation';

export interface EvaluateMissionRuntimeEnv {
  GEMINI_API_KEY?: string;
  GEMINI_MODEL?: string;
}

export const DEFAULT_GEMINI_MODEL = 'gemini-3.8-flash';
export const EVALUATION_RUBRIC_VERSION = '2026.11-v1';
export const EDUCATIONAL_DISCLAIMER =
  'Educational Simulation Disclaimer: This engineering evaluation was generated by Google Gemini using mission telemetry and NASA systems engineering principles for educational and training purposes only. It is not an official flight-readiness certification.';

export const CATEGORY_MAX_POINTS: Record<AiCategoryKey, number> = {
  science: 35,
  reliability: 25,
  resourceEfficiency: 15,
  communications: 15,
  riskManagement: 10,
};

const VALID_ASSESSMENTS = new Set<AiAssessment>(['GO', 'CAUTION', 'NO-GO']);
const VALID_SEVERITIES = new Set<AiDeductionItem['severity']>(['LOW', 'MEDIUM', 'HIGH', 'CRITICAL']);
const CATEGORY_KEYS: AiCategoryKey[] = [
  'science',
  'reliability',
  'resourceEfficiency',
  'communications',
  'riskManagement',
];

const MAX_REQUEST_BYTES = 65_536;
const RATE_LIMIT_WINDOW_MS = 60_000;
const RATE_LIMIT_MAX_REQUESTS = 30;
const GEMINI_TIMEOUT_MS = 20_000;

const evaluationCache = new Map<string, AiMissionEvaluationReport>();
const rateLimitBuckets = new Map<string, number[]>();

export function clearEvaluationCacheForTest(): void {
  evaluationCache.clear();
  rateLimitBuckets.clear();
}

function round1(value: number): number {
  return Math.round(value * 10) / 10;
}

function stableSortValue(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map(stableSortValue);
  }
  if (value && typeof value === 'object') {
    const obj = value as Record<string, unknown>;
    const sorted: Record<string, unknown> = {};
    for (const key of Object.keys(obj).sort()) {
      sorted[key] = stableSortValue(obj[key]);
    }
    return sorted;
  }
  return value;
}

export function computeMissionSnapshotHash(payload: MissionEvaluationRequestPayload): string {
  const canonical = JSON.stringify(stableSortValue(payload));
  let h1 = 0x811c9dc5;
  let h2 = 0x811c9dc5;
  for (let i = 0; i < canonical.length; i++) {
    const ch = canonical.charCodeAt(i);
    h1 ^= ch;
    h1 = Math.imul(h1, 0x01000193);
    h2 ^= ch ^ (i & 0xff);
    h2 = Math.imul(h2, 0x01000193);
  }
  const part1 = (h1 >>> 0).toString(16).padStart(8, '0');
  const part2 = (h2 >>> 0).toString(16).padStart(8, '0');
  return `${part1}${part2}`;
}

function checkRateLimit(clientKey: string, nowMs = Date.now()): boolean {
  const existing = rateLimitBuckets.get(clientKey) ?? [];
  const recent = existing.filter((ts) => nowMs - ts < RATE_LIMIT_WINDOW_MS);
  if (recent.length >= RATE_LIMIT_MAX_REQUESTS) {
    rateLimitBuckets.set(clientKey, recent);
    return false;
  }
  recent.push(nowMs);
  rateLimitBuckets.set(clientKey, recent);
  return true;
}

function validateMissionPayload(raw: unknown): raw is MissionEvaluationRequestPayload {
  if (!raw || typeof raw !== 'object') return false;
  const p = raw as Partial<MissionEvaluationRequestPayload>;
  if (typeof p.runId !== 'string' || p.runId.trim().length === 0) return false;
  if (!p.scenario || typeof p.scenario.code !== 'string' || typeof p.scenario.celestialBody !== 'string') {
    return false;
  }
  if (!p.bus || typeof p.bus.id !== 'string') return false;
  if (!Array.isArray(p.instruments)) return false;
  if (!Array.isArray(p.subsystems)) return false;
  if (!p.orbit || typeof p.orbit.altitudePerigeeKm !== 'number') return false;
  if (!p.launchVehicle || typeof p.launchVehicle.id !== 'string') return false;
  if (!p.operationsPlan || typeof p.operationsPlan.missionDurationDays !== 'number') return false;
  if (!p.engineering || typeof p.engineering.mass !== 'object') return false;
  if (!p.simulation || typeof p.simulation.outcome !== 'string') return false;
  if (!p.deterministicScore || typeof p.deterministicScore.totalScore !== 'number') return false;
  return true;
}

const GEMINI_RESPONSE_SCHEMA = {
  type: 'OBJECT',
  required: [
    'overallScore',
    'categoryScores',
    'assessment',
    'summary',
    'strengths',
    'deductions',
    'criticalFailures',
    'engineeringRationale',
    'limitations',
  ],
  properties: {
    overallScore: { type: 'NUMBER' },
    categoryScores: {
      type: 'OBJECT',
      required: ['science', 'reliability', 'resourceEfficiency', 'communications', 'riskManagement'],
      properties: {
        science: { type: 'NUMBER' },
        reliability: { type: 'NUMBER' },
        resourceEfficiency: { type: 'NUMBER' },
        communications: { type: 'NUMBER' },
        riskManagement: { type: 'NUMBER' },
      },
    },
    assessment: {
      type: 'STRING',
      enum: ['GO', 'CAUTION', 'NO-GO'],
    },
    summary: { type: 'STRING' },
    strengths: {
      type: 'ARRAY',
      items: { type: 'STRING' },
    },
    deductions: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        required: [
          'category',
          'points',
          'finding',
          'engineeringImpact',
          'recommendedCorrection',
          'severity',
        ],
        properties: {
          category: {
            type: 'STRING',
            enum: ['science', 'reliability', 'resourceEfficiency', 'communications', 'riskManagement'],
          },
          points: { type: 'NUMBER' },
          finding: { type: 'STRING' },
          engineeringImpact: { type: 'STRING' },
          recommendedCorrection: { type: 'STRING' },
          severity: {
            type: 'STRING',
            enum: ['LOW', 'MEDIUM', 'HIGH', 'CRITICAL'],
          },
        },
      },
    },
    criticalFailures: {
      type: 'ARRAY',
      items: { type: 'STRING' },
    },
    engineeringRationale: {
      type: 'ARRAY',
      items: { type: 'STRING' },
    },
    limitations: {
      type: 'ARRAY',
      items: { type: 'STRING' },
    },
  },
};

function buildSystemPrompt(): string {
  const refs = getNasaReferenceList()
    .map((r) => `- ${r.code} (${r.version}): ${r.title} [${r.basis}]`)
    .join('\n');

  return [
    'You are an independent NASA Spacecraft Systems Engineering Review Board evaluating a simulated space mission.',
    'Evaluate strictly from the provided spacecraft configuration, engineering margins, orbital mechanics, operations plan, and simulation telemetry.',
    'Never invent telemetry, components, or flight events not present in the mission payload.',
    'Keep the deterministic simulation score separate from your independent systems engineering assessment; use it only as telemetry context.',
    '',
    'SCORING RUBRIC (Total = 100 points):',
    '- science (0 to 35 points): Payload suitability for primary objective & target celestial body, spectral/night/cloud capability, duty cycle, resolution, and regions mapped.',
    '- reliability (0 to 25 points): Launch vehicle reliability, system health, anomaly resolution, thermal/power survival, and mission completion.',
    '- resourceEfficiency (0 to 15 points): Mass margin vs bus/launcher caps, power generation/eclipse DoD margin, and budget efficiency.',
    '- communications (0 to 15 points): Link margin dB, downlink cadence, data captured vs downlinked, and data lost to buffer overflow.',
    '- riskManagement (0 to 10 points): Pre-launch engineering gate posture, ODAR/de-orbit compliance, risk acknowledgment, and operations safety reserves.',
    '',
    'REQUIREMENTS:',
    '- overallScore MUST equal the exact sum of the five categoryScores.',
    '- Each category score MUST stay within its [0, max] bounds.',
    '- Every deduction MUST have points > 0 and <= that category max, and cite a concrete finding, engineeringImpact, and recommendedCorrection.',
    '- Cite relevant NASA standards in engineeringRationale using only the provided reference catalog:',
    refs,
  ].join('\n');
}

function buildUserPrompt(payload: MissionEvaluationRequestPayload): string {
  return JSON.stringify(
    {
      rubricVersion: EVALUATION_RUBRIC_VERSION,
      mission: payload,
    },
    null,
    2
  );
}

function isStringArray(value: unknown): value is string[] {
  return Array.isArray(value) && value.every((item) => typeof item === 'string');
}

export function validateAndBuildGeminiReport(params: {
  rawJson: unknown;
  model: string;
  snapshotHash: string;
}): { ok: true; report: AiMissionEvaluationReport } | { ok: false; error: string } {
  const { rawJson, model, snapshotHash } = params;
  if (!rawJson || typeof rawJson !== 'object') {
    return { ok: false, error: 'Gemini response must be a JSON object.' };
  }

  const r = rawJson as Record<string, unknown>;
  if (typeof r.overallScore !== 'number' || !Number.isFinite(r.overallScore)) {
    return { ok: false, error: 'Missing or invalid overallScore.' };
  }
  if (!r.categoryScores || typeof r.categoryScores !== 'object') {
    return { ok: false, error: 'Missing categoryScores object.' };
  }

  const rawCategories = r.categoryScores as Record<string, unknown>;
  const categoryScores = {} as AiCategoryScores;
  let sum = 0;

  for (const key of CATEGORY_KEYS) {
    const val = rawCategories[key];
    const max = CATEGORY_MAX_POINTS[key];
    if (typeof val !== 'number' || !Number.isFinite(val) || val < 0 || val > max) {
      return {
        ok: false,
        error: `Category "${key}" score must be between 0 and ${max}.`,
      };
    }
    const rounded = round1(val);
    categoryScores[key] = rounded;
    sum += rounded;
  }

  const roundedSum = round1(sum);
  if (Math.abs(roundedSum - r.overallScore) > 0.2 || r.overallScore < 0 || r.overallScore > 100) {
    return {
      ok: false,
      error: `overallScore (${r.overallScore}) does not match sum of categoryScores (${roundedSum}).`,
    };
  }

  if (typeof r.assessment !== 'string' || !VALID_ASSESSMENTS.has(r.assessment as AiAssessment)) {
    return { ok: false, error: 'Invalid assessment value; expected GO, CAUTION, or NO-GO.' };
  }

  if (typeof r.summary !== 'string' || r.summary.trim().length === 0) {
    return { ok: false, error: 'Missing or empty summary.' };
  }

  if (
    !isStringArray(r.strengths) ||
    !isStringArray(r.criticalFailures) ||
    !isStringArray(r.engineeringRationale) ||
    !isStringArray(r.limitations)
  ) {
    return {
      ok: false,
      error: 'Expected string arrays for strengths, criticalFailures, engineeringRationale, and limitations.',
    };
  }

  if (!Array.isArray(r.deductions)) {
    return { ok: false, error: 'Missing deductions array.' };
  }

  const validatedDeductions: AiDeductionItem[] = [];
  for (const item of r.deductions) {
    if (!item || typeof item !== 'object') {
      return { ok: false, error: 'Deduction item must be an object.' };
    }
    const d = item as Record<string, unknown>;
    const cat = d.category as AiCategoryKey;
    if (!CATEGORY_KEYS.includes(cat)) {
      return { ok: false, error: `Invalid deduction category "${String(d.category)}".` };
    }
    if (
      typeof d.points !== 'number' ||
      !Number.isFinite(d.points) ||
      d.points <= 0 ||
      d.points > CATEGORY_MAX_POINTS[cat]
    ) {
      return {
        ok: false,
        error: `Invalid deduction points (${String(d.points)}) for category "${cat}".`,
      };
    }
    if (
      typeof d.finding !== 'string' ||
      d.finding.trim().length === 0 ||
      typeof d.engineeringImpact !== 'string' ||
      d.engineeringImpact.trim().length === 0 ||
      typeof d.recommendedCorrection !== 'string' ||
      d.recommendedCorrection.trim().length === 0
    ) {
      return {
        ok: false,
        error: 'Deduction must include non-empty finding, engineeringImpact, and recommendedCorrection.',
      };
    }
    if (
      typeof d.severity !== 'string' ||
      !VALID_SEVERITIES.has(d.severity as AiDeductionItem['severity'])
    ) {
      return { ok: false, error: `Invalid deduction severity "${String(d.severity)}".` };
    }

    validatedDeductions.push({
      category: cat,
      points: round1(d.points),
      finding: d.finding.trim(),
      engineeringImpact: d.engineeringImpact.trim(),
      recommendedCorrection: d.recommendedCorrection.trim(),
      severity: d.severity as AiDeductionItem['severity'],
    });
  }

  return {
    ok: true,
    report: {
      evaluationId: `gng_eval_${snapshotHash}_${Date.now().toString(36)}`,
      evaluationVersion: EVALUATION_RUBRIC_VERSION,
      model,
      snapshotHash,
      overallScore: roundedSum,
      categoryScores,
      assessment: r.assessment as AiAssessment,
      summary: r.summary.trim(),
      strengths: r.strengths.map((s) => s.trim()).filter(Boolean),
      deductions: validatedDeductions,
      criticalFailures: r.criticalFailures.map((s) => s.trim()).filter(Boolean),
      engineeringRationale: r.engineeringRationale.map((s) => s.trim()).filter(Boolean),
      limitations: r.limitations.map((s) => s.trim()).filter(Boolean),
      educationalDisclaimer: EDUCATIONAL_DISCLAIMER,
      evaluatedAtIso: new Date().toISOString(),
    },
  };
}

function extractGeminiCandidateText(data: unknown): string | null {
  if (!data || typeof data !== 'object') return null;
  const obj = data as Record<string, unknown>;
  if (!Array.isArray(obj.candidates) || obj.candidates.length === 0) return null;
  const first = obj.candidates[0] as Record<string, unknown>;
  const content = first?.content as Record<string, unknown> | undefined;
  if (!content || !Array.isArray(content.parts)) return null;
  const texts = content.parts
    .map((part) => (part && typeof part === 'object' ? (part as Record<string, unknown>).text : null))
    .filter((t): t is string => typeof t === 'string' && t.trim().length > 0);
  if (texts.length === 0) return null;
  return texts.join('\n').trim();
}

function isInvalidKeyErrorBody(status: number, bodyText: string): boolean {
  if (status === 401 || status === 403) return true;
  if (status === 400) {
    const lower = bodyText.toLowerCase();
    return (
      lower.includes('api_key_invalid') ||
      lower.includes('api key not valid') ||
      lower.includes('permission_denied')
    );
  }
  return false;
}

function jsonResponse(body: Record<string, unknown>, status: number): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      'Content-Type': 'application/json',
      'Cache-Control': 'no-store',
    },
  });
}

async function fetchGeminiWithTimeoutAndRetry(
  url: string,
  init: RequestInit,
  fetchImpl: typeof fetch
): Promise<{ ok: true; response: Response } | { ok: false; kind: 'TIMEOUT' | 'NETWORK' }> {
  const maxAttempts = 2;
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), GEMINI_TIMEOUT_MS);
    try {
      const response = await fetchImpl(url, {
        ...init,
        signal: controller.signal,
      });
      clearTimeout(timer);
      if (response.status >= 500 && attempt < maxAttempts) {
        continue;
      }
      return { ok: true, response };
    } catch (error) {
      clearTimeout(timer);
      const isAbort =
        error instanceof Error &&
        (error.name === 'AbortError' || error.message.toLowerCase().includes('abort'));
      if (attempt < maxAttempts) {
        continue;
      }
      return { ok: false, kind: isAbort ? 'TIMEOUT' : 'NETWORK' };
    }
  }
  return { ok: false, kind: 'NETWORK' };
}

export async function handleEvaluateMissionRequest(
  request: Request,
  env: EvaluateMissionRuntimeEnv,
  fetchImpl: typeof fetch = fetch
): Promise<Response> {
  if (request.method !== 'POST') {
    return jsonResponse(
      { ok: false, errorCode: 'METHOD_NOT_ALLOWED', error: 'Use POST /api/evaluate-mission.' },
      405
    );
  }

  const clientIp =
    request.headers.get('cf-connecting-ip') ||
    request.headers.get('x-forwarded-for') ||
    'local-dev';
  if (!checkRateLimit(clientIp)) {
    return jsonResponse(
      {
        ok: false,
        errorCode: 'EVALUATION_RATE_LIMITED',
        error: 'Too many evaluation requests. Please wait a moment before retrying.',
      },
      429
    );
  }

  const apiKey = env.GEMINI_API_KEY?.trim();
  if (!apiKey) {
    return jsonResponse(
      {
        ok: false,
        errorCode: 'EVALUATION_CREDENTIALS_MISSING',
        error: 'Gemini mission evaluator is not configured on the server (GEMINI_API_KEY missing).',
      },
      503
    );
  }

  const model = env.GEMINI_MODEL?.trim() || DEFAULT_GEMINI_MODEL;

  let rawBodyText = '';
  try {
    rawBodyText = await request.text();
  } catch {
    return jsonResponse(
      { ok: false, errorCode: 'EVALUATION_INVALID_REQUEST', error: 'Unable to read request body.' },
      400
    );
  }

  if (rawBodyText.length > MAX_REQUEST_BYTES) {
    return jsonResponse(
      { ok: false, errorCode: 'PAYLOAD_TOO_LARGE', error: 'Mission evaluation payload exceeds size limit.' },
      413
    );
  }

  let parsedBody: unknown;
  try {
    parsedBody = JSON.parse(rawBodyText);
  } catch {
    return jsonResponse(
      { ok: false, errorCode: 'EVALUATION_INVALID_REQUEST', error: 'Request body must be valid JSON.' },
      400
    );
  }

  if (!validateMissionPayload(parsedBody)) {
    return jsonResponse(
      {
        ok: false,
        errorCode: 'EVALUATION_INVALID_REQUEST',
        error: 'Mission payload is missing required telemetry, engineering, or simulation fields.',
      },
      400
    );
  }

  const snapshotHash = computeMissionSnapshotHash(parsedBody);
  const cacheKey = `${EVALUATION_RUBRIC_VERSION}:${model}:${snapshotHash}`;
  const cached = evaluationCache.get(cacheKey);
  if (cached) {
    return jsonResponse(
      {
        ok: true,
        cached: true,
        report: {
          ...cached,
          cached: true,
        },
      },
      200
    );
  }

  const geminiUrl = `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(
    model
  )}:generateContent`;

  const fetchResult = await fetchGeminiWithTimeoutAndRetry(
    geminiUrl,
    {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-goog-api-key': apiKey,
      },
      body: JSON.stringify({
        systemInstruction: {
          parts: [{ text: buildSystemPrompt() }],
        },
        contents: [
          {
            role: 'user',
            parts: [{ text: buildUserPrompt(parsedBody) }],
          },
        ],
        generationConfig: {
          temperature: 0,
          responseMimeType: 'application/json',
          responseSchema: GEMINI_RESPONSE_SCHEMA,
        },
      }),
    },
    fetchImpl
  );

  if (!fetchResult.ok) {
    if (fetchResult.kind === 'TIMEOUT') {
      return jsonResponse(
        {
          ok: false,
          errorCode: 'EVALUATION_TIMEOUT',
          error: 'Gemini evaluation timed out before completing. Please retry.',
        },
        504
      );
    }
    return jsonResponse(
      {
        ok: false,
        errorCode: 'EVALUATION_SERVICE_UNAVAILABLE',
        error: 'Unable to reach Gemini evaluation service.',
      },
      502
    );
  }

  const geminiRes = fetchResult.response;
  if (!geminiRes.ok) {
    const errText = await geminiRes.text().catch(() => '');
    if (geminiRes.status === 429) {
      return jsonResponse(
        {
          ok: false,
          errorCode: 'EVALUATION_RATE_LIMITED',
          error: 'Gemini API rate limit reached. Please retry shortly.',
        },
        429
      );
    }
    if (isInvalidKeyErrorBody(geminiRes.status, errText)) {
      return jsonResponse(
        {
          ok: false,
          errorCode: 'EVALUATION_INVALID_CREDENTIALS',
          error: 'Gemini API credentials were rejected by the evaluation service.',
        },
        502
      );
    }
    return jsonResponse(
      {
        ok: false,
        errorCode: 'EVALUATION_SERVICE_UNAVAILABLE',
        error: `Gemini evaluation service returned HTTP ${geminiRes.status}.`,
      },
      502
    );
  }

  let geminiJson: unknown;
  try {
    geminiJson = await geminiRes.json();
  } catch {
    return jsonResponse(
      {
        ok: false,
        errorCode: 'EVALUATION_INVALID_RESPONSE',
        error: 'Gemini API returned non-JSON response body.',
      },
      502
    );
  }

  const candidateText = extractGeminiCandidateText(geminiJson);
  if (!candidateText) {
    return jsonResponse(
      {
        ok: false,
        errorCode: 'EVALUATION_INVALID_RESPONSE',
        error: 'Gemini API response did not include structured evaluation content.',
      },
      502
    );
  }

  let structuredOutput: unknown;
  try {
    structuredOutput = JSON.parse(candidateText);
  } catch {
    return jsonResponse(
      {
        ok: false,
        errorCode: 'EVALUATION_INVALID_RESPONSE',
        error: 'Gemini structured output could not be parsed as JSON.',
      },
      502
    );
  }

  const validated = validateAndBuildGeminiReport({
    rawJson: structuredOutput,
    model,
    snapshotHash,
  });

  if (!validated.ok) {
    return jsonResponse(
      {
        ok: false,
        errorCode: 'EVALUATION_INVALID_RESPONSE',
        error: validated.error,
      },
      502
    );
  }

  evaluationCache.set(cacheKey, validated.report);
  return jsonResponse(
    {
      ok: true,
      cached: false,
      report: validated.report,
    },
    200
  );
}
